/**
 * GatewayKit UI Kit JavaScript - Minified
 * Namespaced to prevent conflicts with other plugins
 */
(function($){'use strict';window.GatewayKit=window.GatewayKit||{};window.GatewayKit.UI={init:function(){this.initTabs();this.initCopyButtons();this.initAccessibilityEnhancements();this.initFocusManagement()},initTabs:function(){var self=this;var $containers=$('.gatewaykit-ui .gatewaykit-ui-tabs');if($containers.length===0)return;$containers.each(function(){var $tabs=$(this);var $list=$tabs.find('.gatewaykit-ui-tabs__list').first();var $buttons=$list.find('.gatewaykit-ui-tabs__tab, [role="tab"]');var $panels=$tabs.find('.gatewaykit-ui-tabs__panel');if($buttons.length===0||$panels.length===0)return;$list.attr('role','tablist');$buttons.each(function(i){var $btn=$(this);var controls=$btn.attr('aria-controls')||$btn.data('target');var $panel=controls?$panels.filter('#'+controls):$();$btn.attr('role','tab');$btn.attr('tabindex',$btn.attr('aria-selected')==='true'?'0':'-1');$btn.on('click',function(e){e.preventDefault();self.activateTab($tabs,$btn,$panel)});$btn.on('keydown',function(e){var key=e.key;if(key==='ArrowRight'||key==='ArrowLeft'){e.preventDefault();var dir=key==='ArrowRight'?1:-1;var next=(i+dir+$buttons.length)%$buttons.length;$buttons.eq(next).trigger('click').focus()}if(key==='Home'){e.preventDefault();$buttons.eq(0).trigger('click').focus()}if(key==='End'){e.preventDefault();$buttons.eq($buttons.length-1).trigger('click').focus()}})});var $activeBtn=$buttons.filter('[aria-selected="true"]').first();if($activeBtn.length){$activeBtn.trigger('click')}else{var $first=$buttons.first();var controls=$first.attr('aria-controls')||$first.data('target');var $panel=controls?$panels.filter('#'+controls):$panels.first();$first.attr('aria-selected','true');self.activateTab($tabs,$first,$panel)}})},activateTab:function($tabs,$btn,$panel){var $list=$tabs.find('.gatewaykit-ui-tabs__list').first();var $buttons=$list.find('.gatewaykit-ui-tabs__tab, [role="tab"]');var $panels=$tabs.find('.gatewaykit-ui-tabs__panel');$buttons.attr('aria-selected','false').attr('tabindex','-1').removeAttr('data-state');$btn.attr('aria-selected','true').attr('tabindex','0').attr('data-state','active');$panels.attr('data-state','inactive').hide();if($panel&&$panel.length){$panel.attr('data-state','active').show()}},initCopyButtons:function(){var self=this;$(document).on('click','.gatewaykit-copy-btn',function(e){e.preventDefault();var $btn=$(this);var $codeContainer=$btn.closest('.gatewaykit-receipt-code');var $codeElement=$codeContainer.length?$codeContainer:$btn.prev('.gatewaykit-receipt-code');var codeText=$codeElement.text().trim();if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(codeText).then(function(){self.showCopyFeedback($btn,true)}).catch(function(err){self.showCopyFeedback($btn,false)})}else{var textArea=document.createElement('textarea');textArea.value=codeText;textArea.style.position='fixed';textArea.style.left='-999999px';textArea.style.top='-999999px';document.body.appendChild(textArea);textArea.focus();textArea.select();try{var successful=document.execCommand('copy');document.body.removeChild(textArea);self.showCopyFeedback($btn,successful)}catch(err){document.body.removeChild(textArea);self.showCopyFeedback($btn,false)}}})},showCopyFeedback:function($btn,success){var originalText=$btn.html();var originalClasses=$btn.attr('class');if(success){$btn.html('<span>✓</span> '+(typeof gatewaykit_ui_vars!=='undefined'?gatewaykit_ui_vars.copied:'Copied!'));$btn.addClass('gatewaykit-copy-btn--success')}else{$btn.html('<span>✗</span> '+(typeof gatewaykit_ui_vars!=='undefined'?gatewaykit_ui_vars.failed:'Failed'));$btn.addClass('gatewaykit-copy-btn--error')}setTimeout(function(){$btn.html(originalText);$btn.attr('class',originalClasses)},2000)},initAccessibilityEnhancements:function(){if($('.gatewaykit-ui').length>0){$('<a href="#gatewaykit-main-content" class="gatewaykit-skip-link">Skip to main content</a>').prependTo('body');$('.gatewaykit-ui .gatewaykit-ui-section, .gatewaykit-ui .gatewaykit-ui-container').attr('id','gatewaykit-main-content').attr('role','main')}$('.gatewaykit-ui input, .gatewaykit-ui select, .gatewaykit-ui textarea').each(function(){var $input=$(this);var id=$input.attr('id');var label=$('label[for="'+id+'"]');if(label.length>0&&!$input.attr('aria-describedby')){var descId=id+'-desc';var desc=label.find('.description');if(desc.length>0){desc.attr('id',descId);$input.attr('aria-describedby',descId)}}});$('.gatewaykit-ui .gatewaykit-toggle-track, .gatewaykit-ui .gatewaykit-copy-btn').each(function(){var $el=$(this);if(!$el.attr('aria-label')&&!$el.text().trim()){var text=$el.closest('.gatewaykit-gateway-toggle, .gatewaykit-receipt-code').find('.gatewaykit-toggle-label, .gatewaykit-receipt-code').text().trim();if(text){$el.attr('aria-label',text)}}})},initFocusManagement:function(){$(document).on('keydown','.gatewaykit-modal',function(e){if(e.key==='Tab'){var $modal=$(this);var $focusable=$modal.find('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])').filter(':visible');var $first=$focusable.first();var $last=$focusable.last();if(e.shiftKey){if(document.activeElement===$first[0]){e.preventDefault();$last.focus()}}else{if(document.activeElement===$last[0]){e.preventDefault();$first.focus()}}}if(e.key==='Escape'){$('.gatewaykit-modal-close').trigger('click')}});$('.gatewaykit-ui button, .gatewaykit-ui input, .gatewaykit-ui select, .gatewaykit-ui textarea, .gatewaykit-ui a').on('focus',function(){$(this).addClass('gatewaykit-focused')}).on('blur',function(){$(this).removeClass('gatewaykit-focused')});$('.gatewaykit-toggle-track').on('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();$(this).trigger('click')}})}};$(document).ready(function(){GatewayKit.UI.init()})})(jQuery);